int main() {
    int n;
    cin >> n;

    vector<int> row;
    row.reserve(n);

    // Start with the first slime
    row.push_back(1);

    // Add the remaining n-1 slimes
    for (int i = 1; i < n; i++) {
        row.push_back(1);

        // While the last two slimes have the same value, combine them
        while (row.size() >= 2 && row[row.size() - 1] == row[row.size() - 2]) {
            int v = row[row.size() - 1];
            row.pop_back();
            row.pop_back();
            row.push_back(v + 1);
        }
    }

    // Output the final state
    for (int i = 0; i < row.size(); i++) {
        if (i > 0) cout << " ";
        cout << row[i];
    }
    cout << endl;

    return 0;
}
