#include <iostream>
#include <vector>

int main() {
    int n;
    std::cin >> n;

    std::vector<int> slimes;
    slimes.reserve(n);

    // Add the first slime
    slimes.push_back(1);

    // Add the remaining n-1 slimes
    for (int i = 1; i < n; i++) {
        slimes.push_back(1);

        // While the last two slimes have the same value, combine them
        while (slimes.size() >= 2 && slimes[slimes.size() - 1] == slimes[slimes.size() - 2]) {
            int v = slimes[slimes.size() - 1];
            slimes.pop_back();
            slimes.pop_back();
            slimes.push_back(v + 1);
        }
    }

    // Output the final state
    for (size_t i = 0; i < slimes.size(); i++) {
        if (i > 0) std::cout << " ";
        std::cout << slimes[i];
    }
    std::cout << std::endl;

    return 0;
}
